package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;
/** Save failure, repeated tap, duplicate cancellation and optimistic-lock coverage. */
public class ReaderSaveSafetyTest extends ReaderSaveTest {
 @Override public void onStart(){Bundle result=new Bundle();try{
  h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");open("learning");String title="保存安全回归 "+System.currentTimeMillis();input(title,"保存等待期间不可继续输入，也不可重复提交。");String id=RecordId();int before=records().length();
  h.js("window.__readerNative=LifeNative;window.__saveCalls=0;LifeNative={call:(a,p,id)=>{if(a==='saveDocument'){__saveCalls++;setTimeout(()=>__readerNative.call(a,p,id),600);}else __readerNative.call(a,p,id)}}");click("#doc-save");check(h.js("document.querySelector('#doc-save').disabled&&document.querySelector('#doc-title').disabled&&document.querySelector('#doc-body').contentEditable==='false'").equals("true"),"Save locks inputs even in WebViews without inert support");h.js("document.querySelector('#doc-save').click();RecordEditor.close().catch(()=>{});RecordEditor.open(null,null,'idea').catch(()=>{})");until("document.querySelector('#doc-mode').textContent==='编辑'&&!document.querySelector('#doc-save').disabled");check(h.js("__saveCalls===1").equals("true")&&records().length()==before+1,"Repeated tap/back/open cannot double save or replace active note");h.js("LifeNative=__readerNative");
  click("#doc-mode");input(title,"失败后也必须保留我的正文。");h.js("LifeNative={call:(a,p,id)=>a==='saveDocument'?setTimeout(()=>nativeReply({id,error:'Synthetic storage failure'}),120):__readerNative.call(a,p,id)}");click("#doc-save");until("!document.querySelector('#doc-save').disabled");check(record(id).getString("note").contains("保存等待期间"),"Failed save leaves stored record unchanged");check(h.js("document.querySelector('#doc-body').textContent.includes('失败后')&&document.querySelector('#doc-body').contentEditable==='true'&&!document.querySelector('#doc-title').disabled").equals("true"),"Failed save restores editable body and controls");check(hasDraft(id),"Failed save retains recoverable draft");h.js("LifeNative=__readerNative");click("#doc-save");until("document.querySelector('#doc-mode').textContent==='编辑'&&!document.querySelector('#doc-save').disabled");check(record(id).getString("note").contains("失败后")&&!hasDraft(id),"Retry succeeds without stale version and clears draft");close();
  open("learning");input(title,"另一条重名记录，取消另存时不能丢失。");String duplicateId=RecordId();click("#doc-save");until("document.querySelector('#confirm-dialog').open");click("#confirm-cancel");until("!document.querySelector('#doc-save').disabled");check(records().length()==before+1&&h.js("document.querySelector('#doc-body').contentEditable==='true'&&document.querySelector('#doc-body').textContent.includes('另一条重名')").equals("true"),"Cancelling duplicate save retains input and unlocks editor");close();check(hasDraft(duplicateId),"Cancelled duplicate is retained only as draft");
  JSONObject original=record(id);h.js("RecordEditor.open("+original+")");until("!!document.querySelector('#doc-body')");input(title,"过期版本的新修改，不能覆盖并发更新。");JSONObject newer=new JSONObject(original.toString()).put("note","并发保存的新正文。");h.call("saveDocument",new JSONObject().put("record",newer).put("expectedVersion",original.getLong("updatedAt")));click("#doc-save");until("!document.querySelector('#doc-save').disabled");check(record(id).getString("note").equals("并发保存的新正文。")&&hasDraft(id),"Stale save cannot overwrite concurrent update; local draft survives");close();
  result.putString("stream","PASS ReaderSaveSafetyTest: "+passed+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable err){try{if(h!=null)h.screenshot("reader-save-safety-failure.png");}catch(Exception ignored){}result.putString("stream","FAIL ReaderSaveSafetyTest after "+passed+": "+err+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
